-- Rollback of 0045 pair visibility. GENERATED by work/oct28/locks/gen_0045.py. Re-runnable.
-- Restores the 37 workspace policies verbatim (read from staging pg_policies Oct 28 2026, the 0035 shape), the 0043 bodies of
-- ari_pref / ari_push_ack, and drops sdr_uid / ae_uid / owner_uid, the fill triggers, app.pairings and the app.pair_* helpers.
-- SAFETY: after rollback every member sees every row again. So it REFUSES while any pairing exists or any row belongs to
-- someone other than the workspace owner, unless the session has  set ari.allow_rollback_0045 = 'yes';  first.

begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
do $$ declare n bigint := 0; t text; begin
  if coalesce(current_setting('ari.allow_rollback_0045', true), '') = 'yes' then return; end if;
  if to_regclass('app.pairings') is not null then
    execute 'select count(*) from app.pairings' into n;
    if n > 0 then raise exception '0045 rollback refused: % pairing rows exist (set ari.allow_rollback_0045 = yes to force)', n; end if;
  end if;
  for t in select table_name from information_schema.columns where table_schema = 'public' and column_name = 'owner_uid'
             and table_name = any(array['people', 'account_briefs', 'account_stage_history', 'research', 'app_changes', 'app_config', 'app_usage', 'ari_notes', 'ari_prefs', 'attachments', 'book', 'brief', 'copy_guidance', 'decisions', 'draft_edits', 'draft_tags', 'emails', 'events', 'hygiene_findings', 'log_entries', 'messages', 'notifications', 'ops', 'plays', 'push_subscriptions', 'push_tokens', 'queue', 'replies', 'scan_heartbeat', 'sent_messages', 'targets', 'task_events', 'tasks', 'threads']) loop
    execute format('select count(*) from public.%I where owner_uid <> %L::uuid', t, 'b14d1605-c766-4684-9a5b-71ffcab6967b') into n;
    if n > 0 then raise exception '0045 rollback refused: % rows in % belong to another user (set ari.allow_rollback_0045 = yes to force)', n, t; end if;
  end loop;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'accounts' and column_name = 'sdr_uid') then
    execute format('select count(*) from public.accounts where sdr_uid <> %L::uuid or ae_uid is not null', 'b14d1605-c766-4684-9a5b-71ffcab6967b') into n;
    if n > 0 then raise exception '0045 rollback refused: % accounts belong to / are shared with another user', n; end if;
  end if;
end $$;
commit;

-- functions back to the 0043 bodies first (they reference owner_uid)
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
CREATE OR REPLACE FUNCTION public.ari_pref(p_key text, p_default jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select p.value from public.ari_prefs p
                    where p.key = p_key
                      and (coalesce(auth.role(), '') not in ('authenticated', 'anon')
                           or public.is_owner() or app.is_member(p.workspace_id))), p_default);
$function$;
CREATE OR REPLACE FUNCTION public.ari_push_ack(p_endpoint text, p_tag text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.push_subscriptions set last_rx_at = now(), last_rx_tag = left(p_tag, 64)
   where endpoint = p_endpoint and revoked_at is null
     and (coalesce(auth.role(), '') not in ('authenticated', 'anon')
          or public.is_owner() or app.is_member(workspace_id));
$function$;
commit;
-- accounts
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
drop policy if exists ae_read on public.accounts;
drop policy if exists owner_all on public.accounts;
create policy owner_all on public.accounts as permissive for all to authenticated
  using ((( SELECT is_owner() AS is_owner) OR ( SELECT app.is_member(accounts.workspace_id) AS is_member)))
  with check ((( SELECT is_owner() AS is_owner) OR ( SELECT app.is_member(accounts.workspace_id) AS is_member)));
drop trigger if exists sdr_fill on public.accounts;
drop index if exists public.accounts_sdr_uid_idx;
drop index if exists public.accounts_ae_uid_idx;
alter table public.accounts drop column if exists ae_uid;
alter table public.accounts drop column if exists sdr_uid;
commit;
